dwr3::boundary_reflectance_filter_material boundary_reflectance_filter_material_from_string(const std::string &str) {
	if (str == "plaster") return dwr3::boundary_reflectance_filter_material::plaster;
	if (str == "wood") return dwr3::boundary_reflectance_filter_material::wood;
	if (str == "concrete") return dwr3::boundary_reflectance_filter_material::concrete;
	throw std::logic_error("Unknown material string \"" + str + "\"");
}

const dwr3::boundary_reflectance_filter_coefficients *dwr3::boundary_reflectance_filter_material_to_coefficients(const boundary_reflectance_filter_material material, const int sample_rate) {
	switch (material) {
		case boundary_reflectance_filter_material::plaster: switch (sample_rate) {
			case 16000: return &plaster_16000;
			case 22050: return &plaster_22050;
			case 32000: return &plaster_32000;
			case 44100: return &plaster_44100;
			case 48000: return &plaster_48000;
			default: throw std::runtime_error(std::string("Sample rate ") + std::to_string(sample_rate) + " is not supported");
		}
		case boundary_reflectance_filter_material::wood: switch (sample_rate) {
			case 16000: return &wood_16000;
			case 22050: return &wood_22050;
			case 32000: return &wood_32000;
			case 44100: return &wood_44100;
			case 48000: return &wood_48000;
			default: throw std::runtime_error(std::string("Sample rate ") + std::to_string(sample_rate) + " is not supported");
		}
		case boundary_reflectance_filter_material::concrete: switch (sample_rate) {
			case 16000: return &concrete_16000;
			case 22050: return &concrete_22050;
			case 32000: return &concrete_32000;
			case 44100: return &concrete_44100;
			case 48000: return &concrete_48000;
			default: throw std::runtime_error(std::string("Sample rate ") + std::to_string(sample_rate) + " is not supported");
		}
		default: throw std::logic_error("Unknown boundary_reflectance_filter_material enum");
	}
	
}
